#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"

// Destination-passing-style entry. Per definition.json:
//   A: [M, K] fp16
//   B: [N, K] fp16
//   C (output): [M, N] fp16, pre-allocated by the eval driver.
// N=28672, K=4096 are pinned by the problem definition; M varies.

void run(torch::Tensor A, torch::Tensor B, torch::Tensor C) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda() && C.is_cuda(),
                "all tensors must be CUDA");
    TORCH_CHECK(A.dtype() == torch::kFloat16, "A must be float16");
    TORCH_CHECK(B.dtype() == torch::kFloat16, "B must be float16");
    TORCH_CHECK(C.dtype() == torch::kFloat16, "C must be float16");
    TORCH_CHECK(A.is_contiguous() && B.is_contiguous() && C.is_contiguous(),
                "all tensors must be contiguous");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2 && C.dim() == 2,
                "A/B/C must be 2D");
    TORCH_CHECK(A.size(1) == B.size(1),
                "inner dim K must match: A is [M, K], B is [N, K]");
    TORCH_CHECK(C.size(0) == A.size(0) && C.size(1) == B.size(0),
                "C must be [M, N] with M=A.size(0), N=B.size(0)");
    TORCH_CHECK(B.size(0) == 28672,
                "N is pinned to 28672 by the problem definition");
    TORCH_CHECK(A.size(1) == 4096,
                "K is pinned to 4096 by the problem definition");

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    problem_011_gemm_n28672_k4096_launcher(A, B, C, stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "fp16 GEMM C = A @ B.T via CUTLASS TensorOp on Sm80; "
        "destination-passing style (C pre-allocated).");
}

#include "kernel.h"

#include <cutlass/gemm/device/gemm.h>
#include <cutlass/numeric_types.h>
#include <cutlass/layout/matrix.h>
#include <cutlass/arch/arch.h>
#include <cutlass/arch/mma.h>

// fp16 GEMM with fp32 accumulation: C = A @ B^T.
//
// Same row-major-to-mixed-layout encoding as the landed problem_004 /
// problem_007 / problem_008 / problem_009 / problem_010 GEMM
// baselines:
//   A: [M, K] row-major  →  RowMajor    with lda = K.
//   B: [N, K] row-major  →  ColumnMajor with ldb = K (this is B^T col-major [K, N]).
//   C: [M, N] row-major  →  RowMajor    with ldc = N.
//
// N=28672 and K=4096 are pinned. The (28672, 4096) shape matches
// Llama 3.1 8B's mlp.gate_up_proj (the fused gate+up projection that
// produces the SiLU input pair). N=28672 is the largest N in the
// cohort B GEMM family; it tiles cleanly at 128 (28672 / 128 = 224
// N-tiles per row-stripe). The cohort partition marks this slug as
// `predictor_hostile` because the per-row B-stream working set is
// 28672 × 4096 × 2 = 224 MiB fp16 — far outside both the 3090 Ti's
// 6 MB L2 and B200's L2 partition, so the predictor must learn the
// cold-streaming behavior on a tile this large.

namespace {

using ElementInputA = cutlass::half_t;
using ElementInputB = cutlass::half_t;
using ElementOutput = cutlass::half_t;
using ElementAccumulator = float;

using LayoutInputA = cutlass::layout::RowMajor;
using LayoutInputB = cutlass::layout::ColumnMajor;
using LayoutOutput = cutlass::layout::RowMajor;

using MMAOp = cutlass::arch::OpClassTensorOp;
using SmArch = cutlass::arch::Sm80;

using ThreadblockShape = cutlass::gemm::GemmShape<128, 128, 32>;
using WarpShape = cutlass::gemm::GemmShape<64, 64, 32>;
using InstructionShape = cutlass::gemm::GemmShape<16, 8, 16>;

using EpilogueOp = cutlass::epilogue::thread::LinearCombination<
    ElementOutput,
    128 / cutlass::sizeof_bits<ElementOutput>::value,
    ElementAccumulator,
    ElementAccumulator>;

using SwizzleThreadBlock =
    cutlass::gemm::threadblock::GemmIdentityThreadblockSwizzle<>;
constexpr int NumStages = 3;

using CutlassGemm = cutlass::gemm::device::Gemm<
    ElementInputA, LayoutInputA,
    ElementInputB, LayoutInputB,
    ElementOutput, LayoutOutput,
    ElementAccumulator,
    MMAOp,
    SmArch,
    ThreadblockShape,
    WarpShape,
    InstructionShape,
    EpilogueOp,
    SwizzleThreadBlock,
    NumStages>;

}  // namespace

void problem_011_gemm_n28672_k4096_launcher(
    const torch::Tensor& A,
    const torch::Tensor& B,
    torch::Tensor& C,
    cudaStream_t stream) {

    const int M = static_cast<int>(A.size(0));
    const int K = static_cast<int>(A.size(1));
    const int N = static_cast<int>(B.size(0));

    auto const* A_ptr =
        reinterpret_cast<ElementInputA const*>(A.data_ptr<at::Half>());
    auto const* B_ptr =
        reinterpret_cast<ElementInputB const*>(B.data_ptr<at::Half>());
    auto* C_ptr =
        reinterpret_cast<ElementOutput*>(C.data_ptr<at::Half>());

    CutlassGemm gemm_operator;

    CutlassGemm::Arguments args(
        {M, N, K},
        {A_ptr, K},
        {B_ptr, K},
        {C_ptr, N},
        {C_ptr, N},
        {1.0f, 0.0f});

    cutlass::Status status = gemm_operator(args, nullptr, stream);
    TORCH_CHECK(
        status == cutlass::Status::kSuccess,
        "CUTLASS GEMM failed: ", cutlassGetStatusString(status));
}

#pragma once

#include <torch/extension.h>
#include <cuda_runtime.h>

// Host launcher for the fp16 GEMM `C = A @ B.T` baseline.
// A: [M, K] fp16 row-major. B: [N, K] fp16 row-major. C: [M, N] fp16
// row-major (destination-passing-style; pre-allocated by the eval
// driver). N and K are problem constants (N=28672, K=4096); M varies
// per workload.
void problem_011_gemm_n28672_k4096_launcher(
    const torch::Tensor& A,
    const torch::Tensor& B,
    torch::Tensor& C,
    cudaStream_t stream);
